import {chromium} from 'playwright';
import assert from 'node:assert/strict';
import {mkdir,writeFile,readFile} from 'node:fs/promises';
import {resolve} from 'node:path';

// Run after npm run build and npm run preview. Synthetic fixture is generated by scripts/generate-fixtures.mjs.
const origin=process.env.BASE_URL||'http://127.0.0.1:4318';
const fixture=resolve('artifacts/ocr-fixtures/table-clean.png');
const report={schemaVersion:1,synthetic:true,origin,startedAt:new Date().toISOString(),cases:[],errors:[]};
await mkdir('artifacts',{recursive:true});
const browser=await chromium.launch({channel:'msedge',headless:true});
try{
 const context=await browser.newContext();
 await context.addInitScript(()=>{
  const Native=window.Worker;window.asyncProbe={workers:0,terminated:0};
  window.Worker=new Proxy(Native,{construct(Target,args){const worker=new Target(...args);window.asyncProbe.workers++;const stop=worker.terminate.bind(worker);worker.terminate=()=>{window.asyncProbe.terminated++;stop();};return worker;}});
 });
 const page=await context.newPage();page.on('pageerror',e=>report.errors.push({case:'cancel-retry',message:e.message}));page.on('dialog',d=>d.accept());
 const held=[];
 await page.route('**/vendor/worker.min.js',route=>{held.push(route);});
 await page.goto(origin);
 await page.locator('[data-action="import"]').first().click();
 await page.locator('#image-input').setInputFiles(fixture);
 await page.locator('#canvas-host canvas').waitFor();
 await page.locator('[data-action="recognize"]').click();
 await page.waitForFunction(()=>window.asyncProbe.workers===1);
 await page.evaluate(()=>{document.querySelector('[data-action="cancel-ocr"]').click();document.querySelector('[data-action="recognize"]').click();});
 await page.waitForFunction(()=>window.asyncProbe.workers===2);
 // The old recognition's catch/finally has now run; it must not clear the new task's busy state.
 await page.waitForTimeout(250);
 assert.equal(await page.locator('[data-action="cancel-ocr"]').count(),1);
 assert.equal(await page.locator('[data-action="recognize"]').isDisabled(),true);
 assert.equal(await page.locator('.review-row').count(),0);
 await page.locator('[data-action="cancel-ocr"]').click();
 const probe=await page.evaluate(()=>window.asyncProbe);
 assert.ok(probe.terminated>=2,'Both initialization workers must terminate');
 for(const route of held)await route.continue().catch(()=>{});
 await page.waitForTimeout(350);
 assert.equal(await page.locator('[data-action="cancel-ocr"]').count(),0);
 assert.equal(await page.locator('.review-row').count(),0);
 assert.match(await page.locator('.recognition-actions [role="status"]').innerText(),/已取消/);
 report.cases.push({name:'cancel-initialization-and-immediate-retry',passed:true,workers:probe.workers,terminated:probe.terminated,newTaskRetainedBusyState:true,obsoleteRows:0});
 await context.close();

 const delayed=await browser.newContext();
 await delayed.addInitScript(()=>{
  const read=Blob.prototype.arrayBuffer,releaseURL=URL.revokeObjectURL;
  window.decodeProbe={started:false,released:false,revoked:0};
  Blob.prototype.arrayBuffer=async function(...args){if(this.type==='image/png'){window.decodeProbe.started=true;await new Promise(resolve=>{window.releaseDecode=()=>{window.decodeProbe.released=true;resolve();};});}return read.apply(this,args);};
  URL.revokeObjectURL=function(...args){window.decodeProbe.revoked++;return releaseURL.apply(this,args);};
 });
 const decodePage=await delayed.newPage();decodePage.on('pageerror',e=>report.errors.push({case:'late-decode',message:e.message}));decodePage.on('dialog',d=>d.accept());
 await decodePage.goto(origin);
 await decodePage.locator('[data-action="import"]').first().click();
 await decodePage.locator('#image-input').setInputFiles(fixture);
 await decodePage.waitForFunction(()=>window.decodeProbe.started);
 await decodePage.locator('[data-action="close-panel"]').click();
 await decodePage.evaluate(()=>window.releaseDecode());
 await decodePage.waitForFunction(()=>window.decodeProbe.revoked>=1);
 await decodePage.locator('[data-action="import"]').first().click();
 assert.equal(await decodePage.locator('#canvas-host canvas').count(),0);
 assert.equal(await decodePage.locator('#image-select').count(),0);
 assert.equal(await decodePage.locator('[data-action="recognize"]').isDisabled(),true);
 report.cases.push({name:'late-image-decode-after-return',passed:true,probe:await decodePage.evaluate(()=>window.decodeProbe),retainedCanvases:0});
 await delayed.close();
 const imageBytes=await readFile(fixture);
 for(const scenario of ['preserve-edits-during-decode','recognize-during-decode-and-continue-selection']){
  const pendingContext=await browser.newContext();
  await pendingContext.addInitScript(()=>{
   const read=Blob.prototype.arrayBuffer,revoke=URL.revokeObjectURL;
   window.pendingProbe={armed:false,started:false,revoked:0};
   Blob.prototype.arrayBuffer=async function(...args){if(this.type==='image/png'&&window.pendingProbe.armed){window.pendingProbe.armed=false;window.pendingProbe.started=true;await new Promise(resolve=>{window.releasePendingImage=resolve;});}return read.apply(this,args);};
   URL.revokeObjectURL=function(...args){window.pendingProbe.revoked++;return revoke.apply(this,args);};
  });
  const pendingPage=await pendingContext.newPage();pendingPage.on('pageerror',e=>report.errors.push({case:scenario,message:e.message}));pendingPage.on('dialog',d=>d.accept());
  const heldWorkers=[];await pendingPage.route('**/vendor/worker.min.js',route=>{heldWorkers.push(route);});
  const checks={};
  try{
   await pendingPage.goto(origin);await pendingPage.locator('[data-action="import"]').first().click();
   await pendingPage.locator('#image-input').setInputFiles({name:'first.png',mimeType:'image/png',buffer:imageBytes});
   await pendingPage.locator('#canvas-host canvas').waitFor();
   await pendingPage.locator('[data-action="manual"]').click();
   await pendingPage.locator('[data-field="name"]').first().fill('编辑前合成基金');
   await pendingPage.locator('[data-field="marketValue"]').first().fill('100.00');
   await pendingPage.evaluate(()=>{window.pendingProbe.armed=true;});
   await pendingPage.locator('#image-input').setInputFiles({name:'second.png',mimeType:'image/png',buffer:imageBytes});
   await pendingPage.waitForFunction(()=>window.pendingProbe.started);
   if(scenario==='preserve-edits-during-decode'){
    await pendingPage.locator('[data-field="name"]').first().fill('延迟期间修改合成基金');
    await pendingPage.locator('[data-field="marketValue"]').first().fill('987.65');
    await pendingPage.evaluate(()=>window.releasePendingImage());
    await pendingPage.waitForFunction(()=>window.pendingProbe.revoked===2);
    await pendingPage.waitForFunction(()=>document.querySelectorAll('#image-select option').length===2);
    checks.namePreserved=(await pendingPage.locator('[data-field="name"]').first().inputValue())==='延迟期间修改合成基金';
    checks.amountPreserved=(await pendingPage.locator('[data-field="marketValue"]').first().inputValue())==='987.65';
   }else{
    await pendingPage.locator('[data-action="recognize"]').click();
    checks.recognitionRejected=(await pendingPage.locator('[data-action="cancel-ocr"]').count())===0;
    checks.waitMessage=/稍候|稍后|读取|解码|处理中/.test(await pendingPage.locator('.notification').allTextContents().then(x=>x.join(' ')));
    if(await pendingPage.locator('[data-action="cancel-ocr"]').count())await pendingPage.locator('[data-action="cancel-ocr"]').click();
    await pendingPage.evaluate(()=>window.releasePendingImage());
    await pendingPage.waitForFunction(()=>window.pendingProbe.revoked===2);
    checks.pendingImageRetained=await pendingPage.locator('#image-select option').count()===2;
    await pendingPage.locator('#image-input').setInputFiles({name:'third.png',mimeType:'image/png',buffer:imageBytes});
    await pendingPage.waitForFunction(()=>document.querySelectorAll('#image-select option').length===3,{},{timeout:3000}).catch(()=>{});
    checks.thirdImageAccepted=await pendingPage.locator('#image-select option').count()===3;
   }
   report.cases.push({name:scenario,passed:Object.values(checks).every(Boolean),checks});
  }catch(error){report.cases.push({name:scenario,passed:false,checks,error:error.message});}
  finally{for(const route of heldWorkers)await route.abort().catch(()=>{});await pendingContext.close();}
 }
 assert.deepEqual(report.errors,[]);assert.ok(report.cases.every(c=>c.passed),'Async regression failed; see artifacts/async-report.json');report.passed=true;
 console.log('Async cancellation/retry and late image decode checks passed.');
}catch(error){report.passed=false;report.failure=error.message;throw error;}
finally{report.finishedAt=new Date().toISOString();await writeFile('artifacts/async-report.json',JSON.stringify(report,null,2));await browser.close();}
